css:
.Btn {
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background-color: transparent;
  position: relative;
  /* overflow: hidden; */
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.3s;
}

.svgContainer {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: transparent;
  backdrop-filter: blur(4px);
  letter-spacing: 0.8px;
  border-radius: 10px;
  transition: all 0.3s;
  border: 1px solid rgba(156, 156, 156, 0.466);
}

.BG {
  position: absolute;
  content: "";
  width: 100%;
  height: 100%;
  background: #24292e;
  background: -moz-linear-gradient(
    45deg,
    #24292e 0%,
    #1b1f23 50%,
    #111418 100%
  );
  background: -webkit-linear-gradient(
    45deg,
    #24292e 0%,
    #1b1f23 50%,
    #111418 100%
  );
  background: linear-gradient(45deg, #24292e 0%, #1b1f23 50%, #111418 100%);
  filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#24292e', endColorstr='#111418',GradientType=1 );
  z-index: -1;
  border-radius: 9px;
  pointer-events: none;
  transition: all 0.3s;
}

.Btn:hover .BG {
  transform: rotate(35deg);
  transform-origin: bottom;
}

.Btn:hover .svgContainer {
  background-color: rgba(156, 156, 156, 0.466);
}
